const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const FOLDERS = {
  uploaded_pdfs: '10A0EiuyCodhhWBDEnC_1QG301NCczWws',
  generated_content: '1dfFLfZx3uIgstp0iGOvP9hPDLC3SaPpT',
  final_outputs: '1yxxMEjUt6gNky3SWzGnTxYxoo64LehB_',
  logs_debug: '11YmnnsEeoLUbEdOIuRqIB3i2b49XJMzJ',
};
const body = $json.body || $json || {};
const binaryKeys = Object.keys($binary || {});
if (!binaryKeys.length) throw new Error('No PDF file uploaded');
const key = binaryKeys.includes('pdf_file') ? 'pdf_file' : (binaryKeys.includes('file') ? 'file' : binaryKeys[0]);
const meta = $binary[key];
const originalName = meta.fileName || body.fileName || 'uploaded.pdf';
if (!originalName.toLowerCase().endsWith('.pdf') && meta.mimeType !== 'application/pdf') throw new Error('Uploaded file must be PDF');

const runId = 'pdf_to_ppt_' + new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14) + '_' + Math.random().toString(36).slice(2,7);
const uploadDir = '/var/lib/n8n/pdf_to_ppt_backend/uploads';
fs.mkdirSync(uploadDir, { recursive: true });
const localPdf = path.join(uploadDir, `${runId}.pdf`);
const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, key);
fs.writeFileSync(localPdf, pdfBuffer);

const env = {
  PATH: '/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin',
  HOME: '/var/lib/n8n',
  PPT_WORKSPACE: '/var/lib/n8n/pdf_to_ppt_backend/workspace',
  PPT_PIPELINE_BASE: '/var/lib/n8n/pdf_to_ppt_backend/workspace/ppt_pipeline',
  PPT_LIBRARY_BASE: '/var/lib/n8n/pdf_to_ppt_backend/workspace/ppt_library',
  PPT_ENV_FILE: '/var/lib/n8n/pdf_to_ppt_backend/workspace/.env',
  PPT_PLANNER_MODEL: 'openai/gpt-4o-mini',
};
const py = '/var/lib/n8n/pdf_to_ppt_backend/.venv-ppt/bin/python';
const script = '/var/lib/n8n/pdf_to_ppt_backend/workspace/ppt_pipeline/scripts/run_ai_pipeline.py';
const proc = spawnSync(py, [script, localPdf], { env, encoding: 'utf8', timeout: 900000, maxBuffer: 1024 * 1024 * 80 });
if (proc.error) throw proc.error;
if (proc.status !== 0) throw new Error(`Backend failed (${proc.status}): ${proc.stderr || proc.stdout}`);
let parsed;
try { parsed = JSON.parse(proc.stdout); } catch (e) { throw new Error('Backend did not return JSON: ' + proc.stdout.slice(0, 1000)); }
if (!parsed.success) throw new Error('Backend returned success=false');
if (!fs.existsSync(parsed.final_pptx)) throw new Error('Final PPTX missing: ' + parsed.final_pptx);

function safeName(name) { return String(name || 'presentation').replace(/[^a-z0-9_.-]+/gi, '_').replace(/^_+|_+$/g, '').slice(0, 90) || 'presentation'; }
function multipartBody(metadata, fileBuffer, mimeType) {
  const boundary = `pdf_to_ppt_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  const delimiter = `--${boundary}\r\n`;
  const close = `\r\n--${boundary}--`;
  const body = Buffer.concat([
    Buffer.from(delimiter),
    Buffer.from('Content-Type: application/json; charset=UTF-8\r\n\r\n'),
    Buffer.from(JSON.stringify(metadata)),
    Buffer.from('\r\n'),
    Buffer.from(delimiter),
    Buffer.from(`Content-Type: ${mimeType}\r\n\r\n`),
    Buffer.isBuffer(fileBuffer) ? fileBuffer : Buffer.from(fileBuffer),
    Buffer.from(close),
  ]);
  return { boundary, body };
}
function fileOrJsonBuffer(filePath, fallbackObj) {
  if (filePath && fs.existsSync(filePath)) return fs.readFileSync(filePath);
  return Buffer.from(JSON.stringify(fallbackObj || {}, null, 2), 'utf8');
}
const project = safeName(body.project_name || path.basename(originalName, path.extname(originalName)) || 'presentation');
const outputDir = parsed.output_dir;
const artifacts = [
  { kind: 'source_pdf', folderId: FOLDERS.uploaded_pdfs, fileName: `${runId}__${project}__source.pdf`, mimeType: 'application/pdf', buffer: pdfBuffer },
  { kind: 'final_pptx', folderId: FOLDERS.final_outputs, fileName: `${runId}__${project}.pptx`, mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation', buffer: fs.readFileSync(parsed.final_pptx) },
  { kind: 'extracted_text', folderId: FOLDERS.generated_content, fileName: `${runId}__${project}__extracted_text.txt`, mimeType: 'text/plain', buffer: fileOrJsonBuffer(path.join(outputDir, 'extraction', 'extracted_text.txt'), { missing: 'extracted_text.txt' }) },
  { kind: 'build_payload', folderId: FOLDERS.generated_content, fileName: `${runId}__${project}__build_payload.json`, mimeType: 'application/json', buffer: fileOrJsonBuffer(parsed.planner?.output || path.join(outputDir, 'planner', 'build_payload.json'), parsed) },
  { kind: 'validation_report', folderId: FOLDERS.logs_debug, fileName: `${runId}__${project}__validation_report.json`, mimeType: 'application/json', buffer: fileOrJsonBuffer(path.join(outputDir, 'planner', 'validation_report.json'), parsed.validation || {}) },
  { kind: 'run_summary', folderId: FOLDERS.logs_debug, fileName: `${runId}__${project}__run_summary.json`, mimeType: 'application/json', buffer: Buffer.from(JSON.stringify({ ...parsed, n8n_run_id: runId, original_file_name: originalName, project_name: body.project_name || null, stdout_tail: proc.stdout.slice(-2000), stderr_tail: proc.stderr.slice(-2000) }, null, 2), 'utf8') },
];
const common = {
  run_id: runId,
  original_file_name: originalName,
  provider: parsed.planner?.provider,
  pdf_pages: parsed.extraction?.page_count,
  text_chars: parsed.extraction?.text_char_count,
  chunks: parsed.extraction?.chunk_count,
  slide_count: parsed.builder?.slide_count,
  validation_valid: parsed.validation?.valid,
  validation_issues: parsed.validation?.issues?.length || 0,
};
const items = [];
for (const artifact of artifacts) {
  const { boundary, body: multipartBuffer } = multipartBody({ name: artifact.fileName, parents: [artifact.folderId] }, artifact.buffer, artifact.mimeType);
  const binary = await this.helpers.prepareBinaryData(multipartBuffer, `${artifact.kind}.multipart.bin`, 'application/octet-stream');
  items.push({ json: { ...common, kind: artifact.kind, target_file_name: artifact.fileName, folder_id: artifact.folderId, content_type: `multipart/related; boundary=${boundary}` }, binary: { body: binary } });
}
return items;

const prepared = $('Prepare Upload Items').all();
const uploaded = $input.all();
const artifacts = {};
for (let i = 0; i < uploaded.length; i++) {
  const meta = prepared[i]?.json || {};
  const drive = uploaded[i]?.json || {};
  artifacts[meta.kind || `item_${i}`] = {
    drive_id: drive.id,
    name: drive.name || meta.target_file_name,
    link: drive.webViewLink || drive.webContentLink,
    mimeType: drive.mimeType,
    folder_id: meta.folder_id,
  };
}
const base = prepared[0]?.json || {};
return [{ json: {
  success: true,
  run_id: base.run_id,
  original_file_name: base.original_file_name,
  provider: base.provider,
  pdf_pages: base.pdf_pages,
  text_chars: base.text_chars,
  chunks: base.chunks,
  slide_count: base.slide_count,
  validation_valid: base.validation_valid,
  validation_issues: base.validation_issues,
  final_ppt_drive_id: artifacts.final_pptx?.drive_id,
  final_ppt_link: artifacts.final_pptx?.link,
  final_ppt_file: artifacts.final_pptx?.name,
  source_pdf_link: artifacts.source_pdf?.link,
  extracted_text_link: artifacts.extracted_text?.link,
  build_payload_link: artifacts.build_payload?.link,
  validation_report_link: artifacts.validation_report?.link,
  run_summary_link: artifacts.run_summary?.link,
  artifacts,
}}];
